<?php require_once __DIR__.'/../includes/functions.php';require_role('student');$s=$pdo->prepare("SELECT t.day_name,t.period_no,t.start_time,t.end_time,s.name subject_name FROM timetables t JOIN students st ON st.class_id=t.class_id AND st.division_id=t.division_id JOIN subjects s ON s.id=t.subject_id WHERE st.user_id=? ORDER BY t.period_no");$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();$pageTitle='My Timetable';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>My Timetable</h1><div class="table-wrap"><table class="table"><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>